// Maps RAM/SRAM addresses to the disassembly's variable names for readable diffs.
// Source: src/core/vars.js (generated by the architect) or, if missing, the .inc files.
import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { REPO_ROOT } from './rom-file.mjs';

export const VARS_JS = join(REPO_ROOT, 'src/core/vars.js');
export const INC_DIR = join(REPO_ROOT, 'reference/zelda1-disassembly/src');

/** Parses .inc text into [{name, addr}] in file order (only ":=" address labels). */
export function parseIncText(text) {
  const out = [];
  for (const raw of text.split(/\r?\n/)) {
    const m = /^\s*([A-Za-z_]\w*)\s*:=\s*\$([0-9A-Fa-f]+)/.exec(raw.replace(/;.*/, ''));
    if (m) out.push({ name: m[1], addr: parseInt(m[2], 16) });
  }
  return out;
}

function sizesFromGaps(list) {
  return list.map((v, i) => {
    const next = list.slice(i + 1).find((w) => w.addr > v.addr);
    const gap = next ? next.addr - v.addr : 1;
    return { ...v, size: gap > 0 && gap <= 0x100 ? gap : 1 };
  });
}

function fromIncDir(dir) {
  const files = readdirSync(dir)
    .filter((f) => f.endsWith('.inc'))
    .sort((a, b) => (a === 'Variables.inc' ? -1 : b === 'Variables.inc' ? 1 : a.localeCompare(b)));
  return files.flatMap((f) => sizesFromGaps(parseIncText(readFileSync(join(dir, f), 'utf8'))));
}

async function fromVarsJs(path) {
  const mod = await import(pathToFileURL(path).href);
  const order = mod.VAR_REGION ? Object.keys(mod.VAR_REGION) : Object.keys(mod);
  const sizes = mod.VAR_SIZE ?? {};
  return order
    .filter((name) => typeof mod[name] === 'number')
    .map((name) => ({ name, addr: mod[name], size: sizes[name] ?? 1 }));
}

export class VarNames {
  constructor(vars, source) {
    this.source = source;
    this.exact = new Map();
    this.covering = new Map();
    for (const v of vars) {
      if (!(v.addr < 0x800 || (v.addr >= 0x6000 && v.addr < 0x8000))) continue;
      if (!this.exact.has(v.addr)) this.exact.set(v.addr, []);
      this.exact.get(v.addr).push(v.name);
      for (let i = 1; i < v.size; i++) {
        if (!this.covering.has(v.addr + i)) this.covering.set(v.addr + i, `${v.name}+${i}`);
      }
    }
  }

  /** Best single name for an address, e.g. "ObjX+3". */
  name(addr) {
    return this.exact.get(addr)?.[0] ?? this.covering.get(addr) ?? null;
  }

  /** All exact aliases for an address. */
  aliases(addr) {
    return this.exact.get(addr) ?? [];
  }

  /** Resolves a variable name (optionally "Name+N") to an address. */
  resolve(text) {
    const m = /^([A-Za-z_]\w*)(?:\+(\d+|\$[0-9a-f]+))?$/i.exec(text);
    if (!m) return null;
    for (const [addr, names] of this.exact) {
      if (names.includes(m[1])) {
        const off = m[2] ? (m[2].startsWith('$') ? parseInt(m[2].slice(1), 16) : Number(m[2])) : 0;
        return addr + off;
      }
    }
    return null;
  }
}

/** Loads names from vars.js, else the .inc files, else returns an empty table. */
export async function loadVarNames({ varsJs = VARS_JS, incDir = INC_DIR } = {}) {
  if (existsSync(varsJs)) {
    try {
      return new VarNames(await fromVarsJs(varsJs), varsJs);
    } catch {
      // fall through to the .inc files
    }
  }
  if (existsSync(incDir)) return new VarNames(fromIncDir(incDir), incDir);
  return new VarNames([], 'none');
}

export function hex(addr, width = 4) {
  return '$' + addr.toString(16).toUpperCase().padStart(width, '0');
}
